css:
.mty-spring-drawer{box-sizing:border-box;width:100%;max-width:340px;padding:12px;border-radius:16px;background:linear-gradient(180deg,#151a27 0%,#0c0f16 100%);border:1px solid rgba(255,255,255,.08);color:#e8ecf6;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.mty-spring-drawer-head{display:flex;align-items:center;gap:10px;margin:0 0 10px;}
.mty-spring-drawer-title{font-size:12.5px;font-weight:620;letter-spacing:-.01em;}
.mty-spring-drawer-toggle{margin-left:auto;box-sizing:border-box;padding:5px 12px;border-radius:999px;border:1px solid rgba(124,199,255,.3);background:rgba(124,199,255,.1);color:#bfe4ff;font:620 11px/1 system-ui,-apple-system,sans-serif;cursor:pointer;transition:background-color .2s ease,transform .12s ease;}
.mty-spring-drawer-toggle:hover{background-color:rgba(124,199,255,.2);}
.mty-spring-drawer-toggle:active{transform:scale(.94);}
.mty-spring-drawer-toggle:focus-visible{outline:2px solid #7cc7ff;outline-offset:2px;}
.mty-spring-drawer-well{position:relative;height:142px;border-radius:12px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);overflow:hidden;}
.mty-spring-drawer-hint{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:10.5px;color:#5c6679;transition:opacity .25s ease;}
.mty-spring-drawer-panel{position:absolute;left:0;right:0;bottom:0;padding:9px 10px 10px;transform:translate3d(0,100%,0);transform-origin:50% 100%;will-change:transform;}
.mty-spring-drawer-row{display:flex;align-items:center;justify-content:space-between;margin:0 0 5px;padding:6px 9px;border-radius:9px;background:rgba(255,255,255,.05);font-size:11px;}
.mty-spring-drawer-k{color:#8b96ad;}
.mty-spring-drawer-v{color:#e8ecf6;font-variant-numeric:tabular-nums;}
.mty-spring-drawer-go{display:block;width:100%;box-sizing:border-box;margin:0;padding:8px;border-radius:9px;border:0;background:linear-gradient(180deg,#68d3ff,#2f9fe0);color:#04121c;font:650 11px/1 system-ui,-apple-system,sans-serif;cursor:pointer;}
.mty-spring-drawer-go:hover{filter:brightness(1.08);}
.mty-spring-drawer-go:focus-visible{outline:2px solid #7cc7ff;outline-offset:2px;}
.mty-spring-drawer-foot{display:flex;align-items:center;justify-content:space-between;margin:8px 2px 0;font:500 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.1em;color:#5c6679;}
@media (prefers-reduced-motion: reduce){
.mty-spring-drawer-toggle{transition:none;}
.mty-spring-drawer-hint{transition:none;}
}

js:
var toggle = root.querySelector('.mty-spring-drawer-toggle');
var panel = root.querySelector('.mty-spring-drawer-panel');
var hint = root.querySelector('.mty-spring-drawer-hint');
var go = root.querySelector('.mty-spring-drawer-go');
var out = root.querySelector('.mty-spring-drawer-x');
var items = Array.prototype.slice.call(root.querySelectorAll('.mty-spring-drawer-row'));
items.push(go);
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var x = 0, v = 0, target = 0, raf = 0, last = 0, open = false;

function render(){
  var sq = Math.max(-0.07, Math.min(0.07, v * 0.014));
  panel.style.transform = 'translate3d(0,' + ((1 - x) * 100).toFixed(2) + '%,0) scaleY(' + (1 + sq).toFixed(3) + ')';
  for (var i = 0; i < items.length; i++){
    items[i].style.transform = 'translate3d(0,' + ((1 - x) * (10 + i * 7)).toFixed(2) + 'px,0)';
    items[i].style.opacity = Math.max(0, Math.min(1, x * 1.6 - i * 0.12)).toFixed(3);
  }
  hint.style.opacity = Math.max(0, 1 - x * 2.2).toFixed(3);
  out.textContent = 'x ' + x.toFixed(2);
}

function step(now){
  if (!root.isConnected) return;
  var dt = Math.max(0.001, Math.min(0.032, (now - last) / 1000)) || 0.016;
  last = now;
  var a = -170 * (x - target) - 17 * v;
  v += a * dt;
  x += v * dt;
  render();
  if (Math.abs(x - target) > 0.001 || Math.abs(v) > 0.004){ raf = requestAnimationFrame(step); }
  else { x = target; v = 0; render(); raf = 0; }
}

function wake(){ if (!raf){ last = performance.now(); raf = requestAnimationFrame(step); } }

function setOpen(next, silent){
  open = next;
  target = open ? 1 : 0;
  root.classList.toggle('mty-spring-drawer-open', open);
  toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  toggle.textContent = open ? 'Close' : 'Options';
  panel.setAttribute('aria-hidden', open ? 'false' : 'true');
  go.tabIndex = open ? 0 : -1;
  if (silent || mq.matches){ x = target; v = 0; render(); return; }
  v += open ? 1.9 : -1.1;
  wake();
}

toggle.addEventListener('click', function(){ setOpen(!open); });
go.addEventListener('click', function(){
  go.textContent = 'Queued';
  setTimeout(function(){ if (!root.isConnected) return; go.textContent = 'Queue export'; }, 1100);
});
setOpen(false, true);

css:
.mty-pendulum-menu{box-sizing:border-box;width:100%;max-width:340px;padding:12px 12px 8px;border-radius:14px;overflow:hidden;background:#0e1017;border:1px solid rgba(255,255,255,.07);color:#e7e9f2;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.mty-pendulum-menu-bar{display:flex;align-items:center;gap:10px;margin:0 0 8px;}
.mty-pendulum-menu-trigger{box-sizing:border-box;padding:5px 12px;border-radius:8px;border:1px solid rgba(139,125,255,.34);background:rgba(139,125,255,.12);color:#c9c1ff;font:620 11px/1 system-ui,-apple-system,sans-serif;cursor:pointer;transition:background-color .2s ease;}
.mty-pendulum-menu-trigger:hover{background-color:rgba(139,125,255,.24);}
.mty-pendulum-menu-trigger:focus-visible{outline:2px solid #8b7dff;outline-offset:2px;}
.mty-pendulum-menu-status{margin-left:auto;font:500 10px/1 ui-monospace,Menlo,monospace;color:#6f7791;}
.mty-pendulum-menu-rig{position:relative;height:98px;}
.mty-pendulum-menu-rail{position:absolute;left:4px;right:4px;top:0;height:2px;border-radius:2px;background:linear-gradient(90deg,rgba(255,255,255,.03),rgba(255,255,255,.22),rgba(255,255,255,.03));}
.mty-pendulum-menu-arm{position:absolute;top:2px;width:66px;margin-left:-33px;display:flex;flex-direction:column;align-items:center;transform-origin:50% 0;will-change:transform;}
.mty-pendulum-menu-arm::before{content:"";position:absolute;top:-3px;left:50%;margin-left:-2.5px;width:5px;height:5px;border-radius:50%;background:#8b7dff;box-shadow:0 0 8px rgba(139,125,255,.7);}
.mty-pendulum-menu-thread{display:block;width:1px;height:var(--mty-pm-len,36px);background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.34));transform-origin:50% 0;transform:scaleY(.04);transition:transform .34s cubic-bezier(.2,.9,.25,1);}
.mty-pendulum-menu-chip{box-sizing:border-box;padding:5px 10px;border-radius:8px;border:1px solid rgba(255,255,255,.12);background:#181c28;color:#dfe2ee;font:600 10.5px/1 system-ui,-apple-system,sans-serif;white-space:nowrap;cursor:pointer;opacity:0;transform:scale(.3);transition:opacity .26s ease,transform .3s cubic-bezier(.2,1.5,.4,1),background-color .18s ease,border-color .18s ease;}
.mty-pendulum-menu-chip:hover{background-color:#212739;border-color:rgba(139,125,255,.45);}
.mty-pendulum-menu-chip:focus-visible{outline:2px solid #8b7dff;outline-offset:2px;}
.mty-pendulum-menu.mty-pendulum-menu-on .mty-pendulum-menu-thread{transform:scaleY(1);}
.mty-pendulum-menu.mty-pendulum-menu-on .mty-pendulum-menu-chip{opacity:1;transform:scale(1);}
.mty-pendulum-menu-arm:nth-child(3) .mty-pendulum-menu-chip{transition-delay:.04s;}
.mty-pendulum-menu-arm:nth-child(4) .mty-pendulum-menu-chip{transition-delay:.08s;}
.mty-pendulum-menu-arm:nth-child(5) .mty-pendulum-menu-chip{transition-delay:.12s;}
.mty-pendulum-menu-chip.mty-pendulum-menu-hit{background-color:rgba(139,125,255,.3);border-color:#8b7dff;color:#fff;}
@media (prefers-reduced-motion: reduce){
.mty-pendulum-menu-chip{transition:opacity .01s linear;transform:scale(1);}
.mty-pendulum-menu-thread{transition:none;transform:scaleY(1);}
}

js:
var trigger = root.querySelector('.mty-pendulum-menu-trigger');
var status = root.querySelector('.mty-pendulum-menu-status');
var arms = Array.prototype.slice.call(root.querySelectorAll('.mty-pendulum-menu-arm'));
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var open = false, raf = 0, last = 0;
var st = [];

for (var i = 0; i < arms.length; i++){
  st.push({ el: arms[i], chip: arms[i].querySelector('.mty-pendulum-menu-chip'), len: (parseFloat(arms[i].getAttribute('data-len')) || 36) + 14, th: 0, w: 0 });
}

function render(){
  for (var i = 0; i < st.length; i++){ st[i].el.style.transform = 'rotate(' + (st[i].th * 57.2958).toFixed(2) + 'deg)'; }
}

function step(now){
  if (!root.isConnected) return;
  var dt = Math.max(0.001, Math.min(0.03, (now - last) / 1000)) || 0.016;
  last = now;
  var moving = false;
  for (var i = 0; i < st.length; i++){
    var s = st[i];
    var acc = -(1500 / s.len) * Math.sin(s.th) - 1.15 * s.w;
    s.w += acc * dt;
    s.th += s.w * dt;
    if (Math.abs(s.th) > 0.002 || Math.abs(s.w) > 0.012){ moving = true; }
    else { s.th = 0; s.w = 0; }
  }
  render();
  raf = moving ? requestAnimationFrame(step) : 0;
}

function wake(){ if (!raf && !mq.matches){ last = performance.now(); raf = requestAnimationFrame(step); } }

function nudge(i, amount){ if (!open || mq.matches) return; st[i].w += amount; wake(); }

function setOpen(next){
  open = next;
  root.classList.toggle('mty-pendulum-menu-on', open);
  trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
  trigger.textContent = open ? 'Close actions' : 'Row actions';
  for (var i = 0; i < st.length; i++){
    st[i].chip.tabIndex = open ? 0 : -1;
    if (open && !mq.matches){ st[i].th = (i % 2 ? -0.62 : 0.62) + i * 0.02; st[i].w = 0; }
    else { st[i].th = 0; st[i].w = 0; }
  }
  render();
  if (open) wake();
}

trigger.addEventListener('click', function(){ setOpen(!open); });

for (var j = 0; j < st.length; j++){
  (function(k){
    var chip = st[k].chip;
    chip.addEventListener('pointerenter', function(){ nudge(k, k % 2 ? -2.4 : 2.4); });
    chip.addEventListener('focus', function(){ nudge(k, 1.5); });
    chip.addEventListener('click', function(){
      status.textContent = chip.textContent + ' applied';
      chip.classList.add('mty-pendulum-menu-hit');
      nudge(k, k % 2 ? -4.6 : 4.6);
      setTimeout(function(){ if (!root.isConnected) return; chip.classList.remove('mty-pendulum-menu-hit'); }, 260);
    });
  })(j);
}

setOpen(false);

css:
.mty-magnet-cta{position:relative;box-sizing:border-box;width:100%;max-width:340px;min-height:154px;padding:14px 14px 30px;border-radius:18px;overflow:hidden;background:radial-gradient(120% 130% at 18% 0%,#1d1435 0%,#0b0a12 68%);border:1px solid rgba(160,120,255,.18);color:#efeaff;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.mty-magnet-cta-field{position:absolute;left:8px;right:8px;top:8px;bottom:8px;display:grid;grid-template-columns:repeat(8,1fr);grid-template-rows:repeat(4,1fr);pointer-events:none;}
.mty-magnet-cta-dot{width:3px;height:3px;border-radius:50%;background:rgba(190,162,255,.42);justify-self:center;align-self:center;will-change:transform;}
.mty-magnet-cta-copy{position:relative;}
.mty-magnet-cta-eyebrow{display:block;font:600 9px/1 ui-monospace,Menlo,monospace;letter-spacing:.2em;text-transform:uppercase;color:#a78bfa;}
.mty-magnet-cta-head{display:block;margin:7px 0 0;font-size:15px;font-weight:650;letter-spacing:-.015em;}
.mty-magnet-cta-actions{position:relative;display:flex;gap:9px;margin:18px 0 0;}
.mty-magnet-cta-primary{position:relative;box-sizing:border-box;padding:9px 17px;border-radius:11px;border:0;overflow:hidden;background:linear-gradient(135deg,#8b5cf6,#d946ef);color:#fff;font:650 12px/1 system-ui,-apple-system,sans-serif;cursor:pointer;will-change:transform;box-shadow:0 8px 22px -12px rgba(217,70,239,.9);}
.mty-magnet-cta-primary:focus-visible{outline:2px solid #e9d5ff;outline-offset:3px;}
.mty-magnet-cta-ghost{position:relative;box-sizing:border-box;padding:9px 15px;border-radius:11px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.05);color:#e6dcff;font:600 12px/1 system-ui,-apple-system,sans-serif;cursor:pointer;will-change:transform;transition:background-color .2s ease;}
.mty-magnet-cta-ghost:hover{background-color:rgba(255,255,255,.11);}
.mty-magnet-cta-ghost:focus-visible{outline:2px solid #c4b5fd;outline-offset:3px;}
.mty-magnet-cta-glow{position:absolute;left:0;top:0;width:96px;height:96px;margin:-48px 0 0 -48px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.5),rgba(255,255,255,0) 68%);opacity:0;pointer-events:none;transition:opacity .22s ease;}
.mty-magnet-cta-primary:hover .mty-magnet-cta-glow{opacity:.75;}
.mty-magnet-cta-label{position:relative;display:inline-block;will-change:transform;}
.mty-magnet-cta-note{position:absolute;left:15px;bottom:11px;font:500 9px/1 ui-monospace,Menlo,monospace;letter-spacing:.16em;text-transform:uppercase;color:#6d648c;}
@media (prefers-reduced-motion: reduce){
.mty-magnet-cta-dot{transform:none;}
.mty-magnet-cta-primary{transform:none;}
.mty-magnet-cta-ghost{transform:none;}
.mty-magnet-cta-glow{transition:none;}
}

js:
var field = root.querySelector('.mty-magnet-cta-field');
var dotEls = Array.prototype.slice.call(root.querySelectorAll('.mty-magnet-cta-dot'));
var btnEls = Array.prototype.slice.call(root.querySelectorAll('.mty-magnet-cta-primary, .mty-magnet-cta-ghost'));
var glow = root.querySelector('.mty-magnet-cta-glow');
var note = root.querySelector('.mty-magnet-cta-note');
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var dots = [], btns = [], px = -999, py = -999, inside = false, raf = 0, last = 0;

function localBox(el){
  var x = 0, y = 0, n = el;
  while (n && n !== root){ x += n.offsetLeft; y += n.offsetTop; n = n.offsetParent; }
  return { cx: x + el.offsetWidth / 2, cy: y + el.offsetHeight / 2 };
}

function measure(){
  dots = [];
  for (var i = 0; i < dotEls.length; i++){
    var b = localBox(dotEls[i]);
    dots.push({ el: dotEls[i], cx: b.cx, cy: b.cy, x: 0, y: 0, vx: 0, vy: 0 });
  }
  btns = [];
  for (var j = 0; j < btnEls.length; j++){
    var c = localBox(btnEls[j]);
    btns.push({ el: btnEls[j], label: btnEls[j].querySelector('.mty-magnet-cta-label'), cx: c.cx, cy: c.cy, x: 0, y: 0, vx: 0, vy: 0 });
  }
}

function step(now){
  if (!root.isConnected) return;
  var dt = Math.max(0.001, Math.min(0.032, (now - last) / 1000)) || 0.016;
  last = now;
  var busy = inside;
  for (var i = 0; i < dots.length; i++){
    var d = dots[i], tx = 0, ty = 0;
    if (inside){
      var ddx = px - d.cx, ddy = py - d.cy;
      var f = 1 / (1 + (ddx * ddx + ddy * ddy) / 2300);
      tx = Math.max(-15, Math.min(15, ddx * f * 0.5));
      ty = Math.max(-15, Math.min(15, ddy * f * 0.5));
    }
    d.vx += (-150 * (d.x - tx) - 16 * d.vx) * dt;
    d.vy += (-150 * (d.y - ty) - 16 * d.vy) * dt;
    d.x += d.vx * dt;
    d.y += d.vy * dt;
    if (Math.abs(d.x) > 0.06 || Math.abs(d.vx) > 0.6 || Math.abs(d.y) > 0.06 || Math.abs(d.vy) > 0.6){ busy = true; }
    d.el.style.transform = 'translate3d(' + d.x.toFixed(2) + 'px,' + d.y.toFixed(2) + 'px,0)';
  }
  for (var j = 0; j < btns.length; j++){
    var b = btns[j], bx = 0, by = 0;
    if (inside){
      var mx = px - b.cx, my = py - b.cy;
      var dist = Math.sqrt(mx * mx + my * my);
      if (dist < 130){
        var pull = (1 - dist / 130) * 0.4;
        bx = Math.max(-16, Math.min(16, mx * pull));
        by = Math.max(-12, Math.min(12, my * pull));
      }
    }
    b.vx += (-210 * (b.x - bx) - 21 * b.vx) * dt;
    b.vy += (-210 * (b.y - by) - 21 * b.vy) * dt;
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    if (Math.abs(b.x) > 0.06 || Math.abs(b.vx) > 0.6 || Math.abs(b.y) > 0.06 || Math.abs(b.vy) > 0.6){ busy = true; }
    b.el.style.transform = 'translate3d(' + b.x.toFixed(2) + 'px,' + b.y.toFixed(2) + 'px,0)';
    b.label.style.transform = 'translate3d(' + (b.x * 0.5).toFixed(2) + 'px,' + (b.y * 0.5).toFixed(2) + 'px,0)';
  }
  raf = busy ? requestAnimationFrame(step) : 0;
}

function wake(){ if (!raf && !mq.matches){ last = performance.now(); raf = requestAnimationFrame(step); } }

root.addEventListener('pointerenter', function(){
  if (mq.matches) return;
  measure();
  inside = true;
  note.textContent = 'field live';
  wake();
});
root.addEventListener('pointermove', function(e){
  if (mq.matches) return;
  var r = root.getBoundingClientRect();
  px = e.clientX - r.left;
  py = e.clientY - r.top;
  if (!dots.length) measure();
  inside = true;
  wake();
});
root.addEventListener('pointerleave', function(){
  inside = false;
  note.textContent = 'field idle';
  wake();
});
root.addEventListener('pointerdown', function(e){
  if (mq.matches) return;
  var r = root.getBoundingClientRect();
  var hx = e.clientX - r.left, hy = e.clientY - r.top;
  for (var i = 0; i < dots.length; i++){
    var d = dots[i];
    var dx = d.cx - hx, dy = d.cy - hy;
    var d2 = dx * dx + dy * dy;
    var mag = 900 / (1 + d2 / 1600);
    var len = Math.sqrt(d2) || 1;
    d.vx += dx / len * mag;
    d.vy += dy / len * mag;
  }
  note.textContent = 'impulse fired';
  wake();
});

var primary = root.querySelector('.mty-magnet-cta-primary');
primary.addEventListener('pointermove', function(e){
  var r = primary.getBoundingClientRect();
  glow.style.left = (e.clientX - r.left) + 'px';
  glow.style.top = (e.clientY - r.top) + 'px';
});
primary.addEventListener('click', function(){ note.textContent = 'deploy queued'; });
measure();

