.mty-elastic-slider{box-sizing:border-box;width:100%;max-width:340px;padding:13px 13px 10px;border-radius:15px;background:linear-gradient(180deg,#0f1512 0%,#0a0d0c 100%);border:1px solid rgba(158,240,26,.14);color:#e6f2e4;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.mty-elastic-slider-head{display:flex;align-items:baseline;justify-content:space-between;margin:0 2px 2px;}
.mty-elastic-slider-label{font-size:12px;font-weight:620;letter-spacing:-.01em;}
.mty-elastic-slider-val{font:650 13px/1 ui-monospace,Menlo,monospace;color:#b7f04a;font-variant-numeric:tabular-nums;}
.mty-elastic-slider-track{position:relative;height:60px;margin:0 0 2px;cursor:grab;touch-action:none;}
.mty-elastic-slider.mty-elastic-slider-dragging .mty-elastic-slider-track{cursor:grabbing;}
.mty-elastic-slider-svg{display:block;width:100%;height:60px;overflow:visible;}
.mty-elastic-slider-band{fill:none;stroke:rgba(255,255,255,.16);stroke-width:2;stroke-linecap:round;stroke-linejoin:round;}
.mty-elastic-slider-fill{fill:none;stroke:#b7f04a;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round;}
.mty-elastic-slider-knob{position:absolute;left:62%;top:50%;box-sizing:border-box;width:20px;height:20px;margin:0;padding:0;border-radius:50%;border:2px solid #0a0d0c;background:#b7f04a;box-shadow:0 3px 10px rgba(0,0,0,.5),0 0 0 0 rgba(183,240,74,.4);cursor:grab;transition:box-shadow .2s ease;}
.mty-elastic-slider-knob:hover{box-shadow:0 3px 10px rgba(0,0,0,.5),0 0 0 6px rgba(183,240,74,.16);}
.mty-elastic-slider-knob:focus-visible{outline:2px solid #dcffa1;outline-offset:3px;}
.mty-elastic-slider.mty-elastic-slider-dragging .mty-elastic-slider-knob{cursor:grabbing;box-shadow:0 3px 10px rgba(0,0,0,.5),0 0 0 9px rgba(183,240,74,.2);}
.mty-elastic-slider-scale{display:flex;justify-content:space-between;margin:0 4px;font:500 9px/1 ui-monospace,Menlo,monospace;letter-spacing:.1em;color:#5d6b5f;}
@media (prefers-reduced-motion: reduce){
.mty-elastic-slider-knob{transition:none;}
}

js:
var track = root.querySelector('.mty-elastic-slider-track');
var knob = root.querySelector('.mty-elastic-slider-knob');
var band = root.querySelector('.mty-elastic-slider-band');
var fill = root.querySelector('.mty-elastic-slider-fill');
var out = root.querySelector('.mty-elastic-slider-val');
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var X0 = 8, X1 = 292, SPAN = X1 - X0;
var pos = X0 + SPAN * 0.62, targetX = pos, vel = 0, bend = 0, bvel = 0;
var drag = false, raf = 0, last = 0;

function label(v){ return (-60 + v * 0.6).toFixed(1) + ' dB'; }

function paint(){
  var y = (30 + bend).toFixed(1);
  var x = pos.toFixed(1);
  band.setAttribute('d', 'M' + X0 + ' 30 L' + x + ' ' + y + ' L' + X1 + ' 30');
  fill.setAttribute('d', 'M' + X0 + ' 30 L' + x + ' ' + y);
  knob.style.left = (pos / 3).toFixed(2) + '%';
  knob.style.transform = 'translate(-50%,-50%) translate(0,' + bend.toFixed(1) + 'px)';
  var value = Math.max(0, Math.min(100, (pos - X0) / SPAN * 100));
  out.textContent = label(value);
  knob.setAttribute('aria-valuenow', String(Math.round(value)));
  knob.setAttribute('aria-valuetext', label(value));
}

function step(now){
  if (!root.isConnected) return;
  var dt = Math.max(0.001, Math.min(0.032, (now - last) / 1000)) || 0.016;
  last = now;
  if (!drag){
    vel += (-260 * (pos - targetX) - 17 * vel) * dt;
    pos += vel * dt;
    bvel += (-220 * bend - 9 * bvel) * dt;
    bend += bvel * dt;
  }
  paint();
  var moving = drag || Math.abs(pos - targetX) > 0.05 || Math.abs(vel) > 0.4 || Math.abs(bend) > 0.05 || Math.abs(bvel) > 0.4;
  if (moving){ raf = requestAnimationFrame(step); }
  else { pos = targetX; vel = 0; bend = 0; bvel = 0; paint(); raf = 0; }
}

function wake(){
  if (mq.matches){ pos = targetX; vel = 0; bend = 0; bvel = 0; paint(); return; }
  if (!raf){ last = performance.now(); raf = requestAnimationFrame(step); }
}

function onMove(e){
  var r = track.getBoundingClientRect();
  var ux = (e.clientX - r.left) / r.width * 300;
  var uy = (e.clientY - r.top) / r.height * 60;
  if (ux < X0){ ux = X0 - (X0 - ux) * 0.34; }
  else if (ux > X1){ ux = X1 + (ux - X1) * 0.34; }
  pos = ux;
  vel = 0;
  bend = mq.matches ? 0 : Math.max(-20, Math.min(20, (uy - 30) * 0.85));
  if (mq.matches){ pos = Math.max(X0, Math.min(X1, ux)); }
  paint();
}

track.addEventListener('pointerdown', function(e){
  drag = true;
  root.classList.add('mty-elastic-slider-dragging');
  try { track.setPointerCapture(e.pointerId); } catch (err) {}
  try { knob.focus({ preventScroll: true }); } catch (err) { knob.focus(); }
  onMove(e);
  wake();
});
track.addEventListener('pointermove', function(e){ if (drag){ onMove(e); } });

function release(){
  if (!drag) return;
  drag = false;
  root.classList.remove('mty-elastic-slider-dragging');
  targetX = Math.max(X0, Math.min(X1, pos));
  wake();
}
track.addEventListener('pointerup', release);
track.addEventListener('pointercancel', release);

knob.addEventListener('keydown', function(e){
  var k = e.key, d = 0;
  if (k === 'ArrowLeft' || k === 'ArrowDown'){ d = -(e.shiftKey ? 10 : 3); }
  else if (k === 'ArrowRight' || k === 'ArrowUp'){ d = e.shiftKey ? 10 : 3; }
  else if (k === 'Home'){ targetX = X0; }
  else if (k === 'End'){ targetX = X1; }
  else { return; }
  e.preventDefault();
  if (d){ targetX = Math.max(X0, Math.min(X1, targetX + d * SPAN / 100)); bvel += d * 1.4; }
  wake();
});

paint();

