var view = root.querySelector('.mty-momentum-rail-view');
var strip = root.querySelector('.mty-momentum-rail-strip');
var cards = Array.prototype.slice.call(root.querySelectorAll('.mty-momentum-rail-card'));
var navs = Array.prototype.slice.call(root.querySelectorAll('.mty-momentum-rail-btn'));
var bar = root.querySelector('.mty-momentum-rail-bar');
var vout = root.querySelector('.mty-momentum-rail-vel');
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var pos = 0, vel = 0, targetPos = 0, snapping = false, drag = false, moved = 0;
var raf = 0, last = 0, lastX = 0, lastT = 0;

function minPos(){ return -Math.max(0, strip.scrollWidth - view.clientWidth); }
function stepSize(){ return cards.length > 1 ? (cards[1].offsetLeft - cards[0].offsetLeft) : 104; }
function indexNow(){ return Math.round(-pos / stepSize()); }

function snapPos(i){
  var s = stepSize();
  var n = Math.max(0, Math.min(cards.length - 1, i));
  return Math.max(minPos(), Math.min(0, -n * s));
}

function paint(){
  strip.style.transform = 'translate3d(' + pos.toFixed(2) + 'px,0,0)';
  bar.style.width = Math.min(100, Math.abs(vel) / 16).toFixed(1) + '%';
  vout.textContent = Math.round(Math.abs(vel)) + ' px/s';
  navs[0].disabled = pos > -1;
  navs[1].disabled = pos <= minPos() + 1;
}

function step(now){
  if (!root.isConnected) return;
  var dt = Math.max(0.001, Math.min(0.032, (now - last) / 1000)) || 0.016;
  last = now;
  var lo = minPos();
  if (!drag){
    if (snapping){
      vel += (-160 * (pos - targetPos) - 23 * vel) * dt;
      pos += vel * dt;
    } else {
      vel *= Math.exp(-2.4 * dt);
      pos += vel * dt;
      if (pos > 0){ vel += (-230 * pos - 27 * vel) * dt; }
      else if (pos < lo){ vel += (-230 * (pos - lo) - 27 * vel) * dt; }
      else if (Math.abs(vel) < 230){ snapping = true; targetPos = snapPos(indexNow()); }
    }
  }
  paint();
  var busy = drag || Math.abs(vel) > 3 || pos > 0.4 || pos < lo - 0.4 || (snapping && Math.abs(pos - targetPos) > 0.4);
  if (busy){ raf = requestAnimationFrame(step); }
  else { pos = snapping ? targetPos : Math.max(lo, Math.min(0, pos)); vel = 0; paint(); raf = 0; }
}

function wake(){ if (!raf){ last = performance.now(); raf = requestAnimationFrame(step); } }

function glide(i){
  snapping = true;
  targetPos = snapPos(i);
  if (mq.matches){ pos = targetPos; vel = 0; paint(); return; }
  wake();
}

view.addEventListener('pointerdown', function(e){
  drag = true;
  snapping = false;
  moved = 0;
  vel = 0;
  lastX = e.clientX;
  lastT = performance.now();
  root.classList.add('mty-momentum-rail-grab');
  try { view.setPointerCapture(e.pointerId); } catch (err) {}
  wake();
});
view.addEventListener('pointermove', function(e){
  if (!drag) return;
  var now = performance.now();
  var dx = e.clientX - lastX;
  var dt = Math.max(8, now - lastT) / 1000;
  var lo = minPos();
  moved += Math.abs(dx);
  var next = pos + dx;
  if (next > 0 || next < lo){ next = pos + dx * 0.35; }
  pos = next;
  vel = mq.matches ? 0 : dx / dt * 0.8;
  lastX = e.clientX;
  lastT = now;
});

function drop(){
  if (!drag) return;
  drag = false;
  root.classList.remove('mty-momentum-rail-grab');
  var lo = minPos();
  if (pos > 0 || pos < lo || Math.abs(vel) < 230 || mq.matches){
    snapping = true;
    targetPos = snapPos(indexNow());
    if (mq.matches){ pos = targetPos; vel = 0; paint(); return; }
  }
  wake();
}
view.addEventListener('pointerup', drop);
view.addEventListener('pointercancel', drop);
view.addEventListener('click', function(e){ if (moved > 6){ e.preventDefault(); e.stopPropagation(); } }, true);

view.addEventListener('wheel', function(e){
  if (Math.abs(e.deltaX) <= Math.abs(e.deltaY)) return;
  snapping = false;
  pos -= e.deltaX;
  vel = mq.matches ? 0 : -e.deltaX * 14;
  wake();
}, { passive: true });

navs[0].addEventListener('click', function(){ glide(indexNow() - 1); });
navs[1].addEventListener('click', function(){ glide(indexNow() + 1); });

for (var i = 0; i < cards.length; i++){
  (function(k){
    cards[k].addEventListener('focus', function(){ glide(k); });
  })(i);
}

paint();

