js:
var stage = root.querySelector('.mty-rope-pull-stage');
var cord = root.querySelector('.mty-rope-pull-cord');
var bead = root.querySelector('.mty-rope-pull-bead');
var state = root.querySelector('.mty-rope-pull-state');
var yank = root.querySelector('.mty-rope-pull-yank');
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var N = 15, SEG = 5.6, AY = 6;
var pts = [], links = [], ax = 120;
var grab = false, gx = 0, gy = 0, on = false, latched = false;
var raf = 0, calm = 0;

function build(){
  ax = Math.round((stage.clientWidth || 300) * 0.62);
  pts = [];
  for (var i = 0; i < N; i++){ pts.push({ x: ax, y: AY + i * SEG, px: ax, py: AY + i * SEG }); }
  cord.textContent = '';
  links = [];
  for (var j = 0; j < N - 1; j++){
    var el = document.createElement('span');
    el.className = 'mty-rope-pull-link';
    cord.appendChild(el);
    links.push(el);
  }
}

function relax(){
  for (var k = 0; k < 4; k++){
    pts[0].x = ax; pts[0].y = AY;
    for (var i = 0; i < N - 1; i++){
      var a = pts[i], b = pts[i + 1];
      var dx = b.x - a.x, dy = b.y - a.y;
      var d = Math.sqrt(dx * dx + dy * dy) || 0.0001;
      var f = (d - SEG) / d * 0.5;
      var ox = dx * f, oy = dy * f;
      if (i > 0){ a.x += ox; a.y += oy; }
      b.x -= ox; b.y -= oy;
    }
    if (grab){ pts[N - 1].x = gx; pts[N - 1].y = gy; }
  }
}

function integrate(dt){
  var g = 1000 * dt * dt;
  for (var i = 1; i < N; i++){
    var p = pts[i];
    var vx = (p.x - p.px) * 0.994, vy = (p.y - p.py) * 0.994;
    p.px = p.x; p.py = p.y;
    p.x += vx; p.y += vy + g;
  }
  relax();
}

function paint(){
  for (var i = 0; i < links.length; i++){
    var a = pts[i], b = pts[i + 1];
    var dx = b.x - a.x, dy = b.y - a.y;
    var len = Math.sqrt(dx * dx + dy * dy);
    var s = links[i].style;
    s.width = (len + 1).toFixed(2) + 'px';
    s.transform = 'translate3d(' + a.x.toFixed(2) + 'px,' + a.y.toFixed(2) + 'px,0) rotate(' + (Math.atan2(dy, dx) * 57.2958).toFixed(2) + 'deg)';
  }
  var t = pts[N - 1];
  bead.style.transform = 'translate3d(' + t.x.toFixed(2) + 'px,' + t.y.toFixed(2) + 'px,0) translate(-50%,-50%)';
}

function setOn(next){
  on = next;
  root.classList.toggle('mty-rope-pull-on', on);
  state.textContent = on ? 'On 2700K' : 'Off';
  yank.setAttribute('aria-pressed', on ? 'true' : 'false');
}

function trip(){
  var restY = AY + SEG * (N - 1);
  var y = pts[N - 1].y;
  if (!latched && y > restY + 22){ latched = true; setOn(!on); }
  else if (latched && y < restY + 9){ latched = false; }
}

function step(){
  if (!root.isConnected) return;
  var before = pts[N - 1].y;
  integrate(1 / 120);
  integrate(1 / 120);
  trip();
  paint();
  var motion = Math.abs(pts[N - 1].y - before) + Math.abs(pts[N - 1].x - pts[N - 1].px);
  calm = (grab || motion > 0.05) ? 0 : calm + 1;
  raf = calm > 24 ? 0 : requestAnimationFrame(step);
}

function wake(){ calm = 0; if (!raf && !mq.matches){ raf = requestAnimationFrame(step); } }

stage.addEventListener('pointerdown', function(e){
  if (mq.matches) return;
  var r = stage.getBoundingClientRect();
  var mx = e.clientX - r.left, my = e.clientY - r.top;
  var t = pts[N - 1];
  if (Math.abs(mx - t.x) > 26 || Math.abs(my - t.y) > 30) return;
  grab = true;
  gx = mx; gy = my;
  root.classList.add('mty-rope-pull-grabbing');
  try { stage.setPointerCapture(e.pointerId); } catch (err) {}
  wake();
});
stage.addEventListener('pointermove', function(e){
  if (!grab) return;
  var r = stage.getBoundingClientRect();
  gx = Math.max(8, Math.min(r.width - 8, e.clientX - r.left));
  gy = Math.max(AY + 12, Math.min(r.height - 6, e.clientY - r.top));
});
function letGo(){
  if (!grab) return;
  grab = false;
  root.classList.remove('mty-rope-pull-grabbing');
  wake();
}
stage.addEventListener('pointerup', letGo);
stage.addEventListener('pointercancel', letGo);

yank.addEventListener('click', function(){
  if (mq.matches){ setOn(!on); return; }
  grab = true;
  gx = pts[N - 1].x;
  gy = AY + SEG * (N - 1) + 30;
  wake();
  setTimeout(function(){ if (!root.isConnected) return; grab = false; wake(); }, 170);
});

build();
relax();
paint();
requestAnimationFrame(function(){
  if (!root.isConnected) return;
  build();
  relax();
  paint();
  if (!mq.matches){ wake(); }
});

