var tile = root.querySelector('.mty-bounce-badge-tile');
var badge = root.querySelector('.mty-bounce-badge-count');
var sub = root.querySelector('.mty-bounce-badge-sub');
var add = root.querySelector('.mty-bounce-badge-add');
var clear = root.querySelector('.mty-bounce-badge-clear');
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var count = 3, y = 0, vy = 0, sq = 0, sqv = 0, th = 0, w = 0, sc = 1, scv = 0, scTarget = 1;
var raf = 0, last = 0;

function paint(){
  var s = Math.max(-0.3, Math.min(0.4, sq));
  badge.style.transform = 'translate3d(0,' + y.toFixed(2) + 'px,0) scale(' + (sc * (1 + s)).toFixed(3) + ',' + (sc * (1 - s)).toFixed(3) + ')';
  tile.style.transform = 'rotate(' + (th * 57.2958).toFixed(2) + 'deg)';
}

function step(now){
  if (!root.isConnected) return;
  var dt = Math.max(0.001, Math.min(0.03, (now - last) / 1000)) || 0.016;
  last = now;
  vy += 2600 * dt;
  y += vy * dt;
  if (y > 0){
    y = 0;
    if (vy > 65){ sqv += vy * 0.008; vy = -vy * 0.44; }
    else { vy = 0; }
  }
  sqv += (-320 * sq - 19 * sqv) * dt;
  sq += sqv * dt;
  w += (-95 * th - 5.6 * w) * dt;
  th += w * dt;
  scv += (-230 * (sc - scTarget) - 17 * scv) * dt;
  sc += scv * dt;
  paint();
  var busy = Math.abs(vy) > 1 || y < -0.4 || Math.abs(sq) > 0.002 || Math.abs(sqv) > 0.02 ||
             Math.abs(th) > 0.002 || Math.abs(w) > 0.01 || Math.abs(sc - scTarget) > 0.002 || Math.abs(scv) > 0.02;
  if (busy){ raf = requestAnimationFrame(step); }
  else { y = 0; vy = 0; sq = 0; sqv = 0; th = 0; w = 0; sc = scTarget; scv = 0; paint(); raf = 0; }
}

function wake(){ if (!raf && !mq.matches){ last = performance.now(); raf = requestAnimationFrame(step); } }

function label(){
  badge.textContent = String(count);
  sub.textContent = count ? (count + (count === 1 ? ' unread mention' : ' unread mentions')) : 'All caught up';
  clear.disabled = count === 0;
  scTarget = count ? 1 : 0;
}

add.addEventListener('click', function(){
  count += 1;
  label();
  if (mq.matches){ sc = 1; paint(); return; }
  sc = 1;
  y = -54;
  vy = 0;
  w += 2.3;
  wake();
});

clear.addEventListener('click', function(){
  count = 0;
  label();
  if (mq.matches){ sc = 0; paint(); return; }
  w -= 1.4;
  wake();
});

label();
paint();

