js:
var well = root.querySelector('.mty-throw-chip-well');
var chip = root.querySelector('.mty-throw-chip-piece');
var trails = Array.prototype.slice.call(root.querySelectorAll('.mty-throw-chip-trail'));
var status = root.querySelector('.mty-throw-chip-status');
var reset = root.querySelector('.mty-throw-chip-reset');
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var W = 300, H = 114, cw = 56, ch = 28;
var x = 150, y = 40, vx = 0, vy = 0, ang = 0, av = 0;
var tp = [{ x: 150, y: 40 }, { x: 150, y: 40 }];
var drag = false, touched = false, raf = 0, last = 0, hx = 0, hy = 0, lx = 0, ly = 0, lt = 0, filed = '';

function measure(){
  W = well.clientWidth || 300;
  H = well.clientHeight || 114;
  cw = chip.offsetWidth || 56;
  ch = chip.offsetHeight || 28;
}

function paint(){
  chip.style.transform = 'translate3d(' + (x - cw / 2).toFixed(2) + 'px,' + (y - ch / 2).toFixed(2) + 'px,0) rotate(' + ang.toFixed(2) + 'deg)';
  for (var i = 0; i < trails.length; i++){
    trails[i].style.transform = 'translate3d(' + (tp[i].x - cw / 2).toFixed(2) + 'px,' + (tp[i].y - ch / 2).toFixed(2) + 'px,0) rotate(' + (ang * 0.6).toFixed(2) + 'deg)';
  }
}

function fileIt(){
  if (!touched) return;
  var name = x < W * 0.42 ? 'Keep' : (x > W * 0.58 ? 'Discard' : 'Unsorted');
  if (name !== filed){
    filed = name;
    status.textContent = name === 'Unsorted' ? 'Resting between bays' : ('Filed to ' + name);
  }
}

function step(now){
  if (!root.isConnected) return;
  var dt = Math.max(0.001, Math.min(0.028, (now - last) / 1000)) || 0.016;
  last = now;
  var minX = cw / 2 + 3, maxX = W - cw / 2 - 3, minY = ch / 2 + 3, maxY = H - ch / 2 - 3;
  if (!drag){
    vy += 1650 * dt;
    var damp = Math.exp(-0.5 * dt);
    vx *= damp;
    vy *= damp;
    x += vx * dt;
    y += vy * dt;
    if (x < minX){ x = minX; vx = -vx * 0.6; av += vy * 0.05; }
    else if (x > maxX){ x = maxX; vx = -vx * 0.6; av -= vy * 0.05; }
    if (y < minY){ y = minY; vy = -vy * 0.6; }
    else if (y >= maxY){
      y = maxY;
      if (vy > 0){ vy = -vy * 0.5; }
      vx *= 0.9;
      av = av * 0.55 + vx * 0.9;
      if (Math.abs(vy) < 55){ vy = 0; }
    }
    ang += av * dt;
    av *= Math.exp(-1.6 * dt);
    if (y >= maxY - 0.6 && Math.abs(vx) < 22 && vy === 0){
      vx *= 0.86;
      av += (-58 * (ang - Math.round(ang / 360) * 360) - 9 * av) * dt;
      fileIt();
    }
  }
  for (var i = 0; i < tp.length; i++){
    var f = 1 - Math.exp(-(15 - i * 6) * dt);
    tp[i].x += (x - tp[i].x) * f;
    tp[i].y += (y - tp[i].y) * f;
  }
  paint();
  var busy = drag || Math.abs(vx) > 2 || Math.abs(vy) > 2 || Math.abs(av) > 2 ||
             Math.abs(tp[0].x - x) > 0.4 || Math.abs(tp[1].x - x) > 0.4 || Math.abs(tp[0].y - y) > 0.4 || Math.abs(tp[1].y - y) > 0.4;
  raf = busy ? requestAnimationFrame(step) : 0;
}

function wake(){ if (!raf && !mq.matches){ last = performance.now(); raf = requestAnimationFrame(step); } }

chip.addEventListener('pointerdown', function(e){
  measure();
  drag = true;
  touched = true;
  filed = '';
  root.classList.add('mty-throw-chip-grabbing');
  try { chip.setPointerCapture(e.pointerId); } catch (err) {}
  var r = well.getBoundingClientRect();
  hx = e.clientX - r.left - x;
  hy = e.clientY - r.top - y;
  lx = x; ly = y; lt = performance.now();
  vx = 0; vy = 0;
  status.textContent = 'Throwing';
  wake();
});

chip.addEventListener('pointermove', function(e){
  if (!drag) return;
  var r = well.getBoundingClientRect();
  var now = performance.now();
  var dt = Math.max(8, now - lt) / 1000;
  x = Math.max(cw / 2 + 3, Math.min(W - cw / 2 - 3, e.clientX - r.left - hx));
  y = Math.max(ch / 2 + 3, Math.min(H - ch / 2 - 3, e.clientY - r.top - hy));
  vx = (x - lx) / dt;
  vy = (y - ly) / dt;
  av = Math.max(-320, Math.min(320, vx * 0.5));
  lx = x; ly = y; lt = now;
  if (mq.matches){ paint(); }
});

function release(){
  if (!drag) return;
  drag = false;
  root.classList.remove('mty-throw-chip-grabbing');
  if (mq.matches){ vx = 0; vy = 0; y = H - ch / 2 - 3; paint(); fileIt(); return; }
  vx = Math.max(-1600, Math.min(1600, vx));
  vy = Math.max(-1600, Math.min(1600, vy));
  wake();
}
chip.addEventListener('pointerup', release);
chip.addEventListener('pointercancel', release);

chip.addEventListener('keydown', function(e){
  var k = e.key;
  if (k === 'ArrowLeft'){ vx -= 420; }
  else if (k === 'ArrowRight'){ vx += 420; }
  else if (k === 'ArrowUp' || k === 'Enter' || k === ' '){ vy -= 560; vx += 180; }
  else { return; }
  e.preventDefault();
  touched = true;
  filed = '';
  av += vx * 0.25;
  if (mq.matches){ x = Math.max(cw / 2 + 3, Math.min(W - cw / 2 - 3, x + (vx > 0 ? 40 : -40))); vx = 0; vy = 0; paint(); fileIt(); return; }
  status.textContent = 'Flicked';
  wake();
});

reset.addEventListener('click', function(){
  measure();
  x = W / 2; y = 36; vx = 0; vy = 0; ang = 0; av = 0;
  touched = false;
  filed = '';
  status.textContent = 'Drag the chip and let go';
  if (mq.matches){ paint(); return; }
  wake();
});

measure();
x = W / 2;
y = 36;
tp[0].x = x; tp[0].y = y; tp[1].x = x; tp[1].y = y;
paint();
if (!mq.matches){ wake(); }

