js:
var arms = [].slice.call(root.querySelectorAll('.mty-newton-cradle-arm'));
var rig = root.querySelector('.mty-newton-cradle-rig');
var valEl = root.querySelector('.mty-newton-cradle-val');
var btns = [].slice.call(root.querySelectorAll('.mty-newton-cradle-btn'));
var N = arms.length, TH = [], OM = [], i;
for (i = 0; i < N; i++) { TH.push(0); OM.push(0); }
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var soft = !!(mq && mq.matches);
var L = 84, G = 2100, DAMP = soft ? 3.2 : 0.28, E = 0.985, MAXW = 4;
var workers = 3, drag = -1, dragPrev = 0, dragT = 0, running = false, last = 0, acc = 0;

function render() {
  for (var k = 0; k < N; k++) arms[k].style.transform = 'rotate(' + TH[k].toFixed(4) + 'rad)';
}
function markWorkers() {
  for (var k = 0; k < N; k++) {
    if (k < workers) arms[k].setAttribute('data-on', '1');
    else arms[k].removeAttribute('data-on');
  }
  valEl.textContent = String(workers);
  btns[0].disabled = workers <= 1;
  btns[1].disabled = workers >= MAXW;
}
function flash(k) {
  var el = arms[k];
  el.setAttribute('data-hit', '1');
  setTimeout(function () { el.removeAttribute('data-hit'); }, 110);
}
function integrate(dt) {
  var k;
  for (k = 0; k < N; k++) {
    if (k === drag) continue;
    OM[k] += (-(G / L) * Math.sin(TH[k]) - DAMP * OM[k]) * dt;
    TH[k] += OM[k] * dt;
  }
  for (k = 0; k < N - 1; k++) {
    if (k === drag || k + 1 === drag) continue;
    if (TH[k] >= TH[k + 1] && OM[k] > OM[k + 1]) {
      var a = OM[k], b = OM[k + 1];
      OM[k] = ((1 - E) * a + (1 + E) * b) / 2;
      OM[k + 1] = ((1 + E) * a + (1 - E) * b) / 2;
      var m = (TH[k] + TH[k + 1]) / 2;
      TH[k] = m; TH[k + 1] = m;
      if (a - b > 0.7) { flash(k); flash(k + 1); }
    }
  }
}
function asleep() {
  if (drag >= 0) return false;
  for (var k = 0; k < N; k++) if (Math.abs(OM[k]) > 0.006 || Math.abs(TH[k]) > 0.004) return false;
  return true;
}
function frame(now) {
  if (!root.isConnected) { running = false; return; }
  acc += Math.min(0.05, (now - last) / 1000);
  last = now;
  while (acc > 0.004) { integrate(0.004); acc -= 0.004; }
  render();
  if (asleep()) {
    for (var k = 0; k < N; k++) { TH[k] = 0; OM[k] = 0; }
    render();
    running = false;
    return;
  }
  requestAnimationFrame(frame);
}
function wake() {
  if (running) return;
  running = true; last = performance.now(); acc = 0;
  requestAnimationFrame(frame);
}
function pulse(n) {
  var amp = soft ? 0.1 : 0.62;
  for (var k = 0; k < N; k++) { TH[k] = k < n ? -amp : 0; OM[k] = 0; }
  wake();
}
btns.forEach(function (b) {
  b.addEventListener('click', function () {
    var d = parseInt(b.getAttribute('data-d'), 10);
    workers = Math.max(1, Math.min(MAXW, workers + d));
    markWorkers();
    pulse(workers);
  });
});
rig.addEventListener('pointerdown', function (e) {
  var best = -1, bd = 1e9, r = rig.getBoundingClientRect(), px = e.clientX - r.left;
  [0, N - 1].forEach(function (k) {
    var c = arms[k].offsetLeft + arms[k].offsetWidth / 2 + Math.sin(TH[k]) * L;
    var d = Math.abs(px - c);
    if (d < bd) { bd = d; best = k; }
  });
  if (bd > 34) return;
  drag = best; dragPrev = TH[best]; dragT = performance.now();
  OM[best] = 0;
  rig.setAttribute('data-drag', '1');
  rig.setPointerCapture(e.pointerId);
  wake();
});
rig.addEventListener('pointermove', function (e) {
  if (drag < 0) return;
  var r = rig.getBoundingClientRect();
  var el = arms[drag];
  var px = el.offsetLeft + el.offsetWidth / 2, py = el.offsetTop;
  var dx = (e.clientX - r.left) - px, dy = Math.max(14, (e.clientY - r.top) - py);
  var a = Math.atan2(dx, dy);
  a = drag === 0 ? Math.max(-0.85, Math.min(0, a)) : Math.min(0.85, Math.max(0, a));
  var now = performance.now(), dt = Math.max(8, now - dragT) / 1000;
  OM[drag] = (a - dragPrev) / dt * 0.6;
  dragPrev = a; dragT = now;
  TH[drag] = a;
});
function endDrag() {
  if (drag < 0) return;
  drag = -1;
  rig.removeAttribute('data-drag');
  wake();
}
rig.addEventListener('pointerup', endDrag);
rig.addEventListener('pointercancel', endDrag);
markWorkers();
render();
setTimeout(function () { if (root.isConnected) pulse(1); }, 420);

