var stage = root.querySelector('.mty-cloth-banner-stage');
var cv = root.querySelector('.mty-cloth-banner-cv');
var act = root.querySelector('.mty-cloth-banner-act');
var ctx = cv.getContext('2d');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var soft = !!(mq && mq.matches);
var COLS = 15, ROWS = 8;
var pts = [], links = [], W = 0, H = 0, restX = 20, restY = 14;
var pinned = true, drag = -1, t = 0, running = false, last = 0, acc = 0;

function build() {
  W = Math.max(160, stage.clientWidth || 280);
  H = Math.max(90, stage.clientHeight || 132);
  var dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  var padX = 8, top = 7;
  restX = (W - padX * 2) / (COLS - 1);
  restY = (H - top - 14) / (ROWS - 1);
  pts = []; links = [];
  var r, c;
  for (r = 0; r < ROWS; r++) for (c = 0; c < COLS; c++) {
    var x = padX + c * restX, y = top + r * restY;
    pts.push({ x: x, y: y, ox: x, oy: y, hx: x, hy: y, pin: r === 0 });
  }
  for (r = 0; r < ROWS; r++) for (c = 0; c < COLS; c++) {
    var i = r * COLS + c;
    if (c < COLS - 1) links.push([i, i + 1, restX]);
    if (r < ROWS - 1) links.push([i, i + COLS, restY]);
