    var p = pts[i];
    if (p.pin && pinned) { p.x = p.hx; p.y = p.hy; p.ox = p.x; p.oy = p.y; continue; }
    if (i === drag) continue;
    var vx = (p.x - p.ox) * 0.982, vy = (p.y - p.oy) * 0.982;
