stage.addEventListener('pointerup', endDrag);
stage.addEventListener('pointercancel', endDrag);
act.addEventListener('click', function () {
  if (pinned) {
    pinned = false;
    stage.setAttribute('data-gone', '1');
    act.textContent = 'Restore';
    if (!soft) { for (var i = 0; i < COLS; i++) { pts[i].oy = pts[i].y + 2; } }
  } else {
    pinned = true; build();
    stage.removeAttribute('data-gone');
    act.textContent = 'Dismiss';
    for (var k = 0; k < pts.length; k++) { pts[k].oy = pts[k].y + 3.2; }
    draw();
  }
