var bin = root.querySelector('.mty-gravity-tags-bin');
var srcs = [].slice.call(root.querySelectorAll('.mty-gravity-tags-chip'));
var clearBtn = root.querySelector('.mty-gravity-tags-clear');
var countEl = root.querySelector('.mty-gravity-tags-count');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var soft = !!(mq && mq.matches);
var items = [], W = 0, H = 0, running = false, last = 0, acc = 0, quiet = 0;
var G = soft ? 4200 : 1650, DT = 1 / 120;

function measure() { W = bin.clientWidth || 260; H = bin.clientHeight || 104; }
function sync() {
  countEl.textContent = String(items.filter(function (b) { return !b.out; }).length);
  clearBtn.disabled = items.filter(function (b) { return !b.out; }).length === 0;
  if (items.length) bin.setAttribute('data-filled', '1');
  else bin.removeAttribute('data-filled');
}
function place(b) {
  b.el.style.transform = 'translate(' + b.x.toFixed(1) + 'px,' + b.y.toFixed(1) + 'px) rotate(' + b.rot.toFixed(3) + 'rad)';
}
function add(src) {
  measure();
  var el = document.createElement('button');
  el.type = 'button';
  el.className = 'mty-gravity-tags-item';
  el.innerHTML = src.textContent + '<span class="mty-gravity-tags-x" aria-hidden="true">&#10005;</span>';
  el.setAttribute('aria-label', 'Remove filter ' + src.textContent);
  bin.appendChild(el);
  var w = el.offsetWidth, h = el.offsetHeight;
  var sr = src.getBoundingClientRect(), br = bin.getBoundingClientRect();
  var b = {
    el: el, src: src, w: w, h: h,
    x: Math.max(2, Math.min(W - w - 2, sr.left - br.left + sr.width / 2 - w / 2)),
    y: -h - 4,
    vx: (Math.random() - 0.5) * 90, vy: 140,
    rot: (Math.random() - 0.5) * 0.3, av: (Math.random() - 0.5) * 3.4, out: false,
    lx: 0, ly: 0, lr: 0
  };
  if (soft) { b.vy = 0; b.av = 0; b.y = H - h - 4 - items.length * 2; }
  items.push(b);
  place(b);
  src.disabled = true;
  el.addEventListener('click', function () { eject(b); });
  sync();
  wake();
}
function eject(b) {
  if (b.out) return;
  b.out = true;
  b.vy = -520 - Math.random() * 120;
  b.vx = (Math.random() - 0.5) * 300;
  b.av = (Math.random() - 0.5) * 9;
  b.el.style.pointerEvents = 'none';
  if (b.src) b.src.disabled = false;
  sync();
  wake();
}
function step(dt) {
  var i, j, b;
  for (i = 0; i < items.length; i++) {
    b = items[i];
    b.vy += G * dt;
    b.x += b.vx * dt; b.y += b.vy * dt;
    b.rot += b.av * dt; b.av *= 0.988;
    if (b.out) continue;
    if (b.x < 1) { b.x = 1; b.vx = -b.vx * 0.36; }
    if (b.x + b.w > W - 1) { b.x = W - b.w - 1; b.vx = -b.vx * 0.36; }
    if (b.y + b.h > H - 2) {
      b.y = H - b.h - 2;
      b.vy = Math.abs(b.vy) > 26 ? -b.vy * 0.24 : 0;
      b.vx *= 0.76; b.av *= 0.4;
      b.av += (-b.rot * 26 - b.av * 7) * dt;
    }
    if (Math.abs(b.rot) > 0.34) { b.rot = b.rot > 0 ? 0.34 : -0.34; b.av *= -0.3; }
  }
  for (var pass = 0; pass < 2; pass++) {
    for (i = 0; i < items.length; i++) {
      if (items[i].out) continue;
      for (j = i + 1; j < items.length; j++) {
        if (items[j].out) continue;
        var a = items[i], c = items[j];
        var dx = (a.x + a.w / 2) - (c.x + c.w / 2), dy = (a.y + a.h / 2) - (c.y + c.h / 2);
        var px = (a.w + c.w) / 2 - Math.abs(dx), py = (a.h + c.h) / 2 - Math.abs(dy);
        if (px <= 0 || py <= 0) continue;
        if (px < py) {
          var sx = dx < 0 ? -1 : 1;
          a.x += sx * px / 2; c.x -= sx * px / 2;
