          a.vx = mvx + (a.vx - mvx) * -0.18; c.vx = mvx + (c.vx - mvx) * -0.18;
        } else {
          var sy = dy < 0 ? -1 : 1;
          a.y += sy * py / 2; c.y -= sy * py / 2;
          var mvy = (a.vy + c.vy) / 2;
          a.vy = mvy + (a.vy - mvy) * -0.14; c.vy = mvy + (c.vy - mvy) * -0.14;
          a.av += sy * 0.5; c.av -= sy * 0.5;
          a.vx *= 0.94; c.vx *= 0.94;
        }
      }
    }
  }
}
function frame(now) {
  if (!root.isConnected) { running = false; return; }
  if (bin.clientHeight !== H || bin.clientWidth !== W) measure();
  acc += Math.min(0.06, (now - last) / 1000); last = now;
  var n = 0;
  while (acc > DT && n < 24) { step(DT); acc -= DT; n++; }
  var moved = 0, flying = false;
  for (var i = items.length - 1; i >= 0; i--) {
    var b = items[i];
    if (b.out && (b.y < -b.h - 30 || b.y > H + 90)) {
      if (b.el.parentNode) b.el.parentNode.removeChild(b.el);
      items.splice(i, 1);
      continue;
    }
    place(b);
    moved += Math.abs(b.x - b.lx) + Math.abs(b.y - b.ly) + Math.abs(b.rot - b.lr) * 24;
    b.lx = b.x; b.ly = b.y; b.lr = b.rot;
    if (b.out) flying = true;
  }
