  if (quiet > 6) { running = false; return; }
  requestAnimationFrame(frame);
}
function wake() {
  if (running) return;
  running = true; last = performance.now(); acc = 0; quiet = 0;
  requestAnimationFrame(frame);
}
srcs.forEach(function (s) { s.addEventListener('click', function () { add(s); }); });
clearBtn.addEventListener('click', function () {
  items.forEach(function (b, i) { setTimeout(function () { if (root.isConnected) eject(b); }, i * 55); });
});
measure();
if (window.ResizeObserver) new ResizeObserver(measure).observe(bin);
setTimeout(function () { if (root.isConnected) add(srcs[0]); }, 260);
setTimeout(function () { if (root.isConnected) add(srcs[1]); }, 520);

