.mty-slosh-gauge{--sg-a:#4fd8e4;padding:13px;border-radius:15px;background:linear-gradient(180deg,#0d151a,#080b0f);border:1px solid rgba(255,255,255,.08);color:#e6f1f4;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}
