var tank = root.querySelector('.mty-slosh-gauge-tank');
var cv = root.querySelector('.mty-slosh-gauge-cv');
var ctx = cv.getContext('2d');
var usedEl = root.querySelector('.mty-slosh-gauge-used');
var pctEl = root.querySelector('.mty-slosh-gauge-pct');
var btns = [].slice.call(root.querySelectorAll('.mty-slosh-gauge-btn'));
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var soft = !!(mq && mq.matches);
var N = 72, h = [], v = [], W = 0, H = 0, i;
for (i = 0; i < N; i++) { h.push(0); v.push(0); }
var TOTAL = 64, used = 38, shown = 38, level = 0, levelV = 0, target = 0;
var running = false, last = 0, acc = 0, drag = false, lastIdx = -1, lastY = 0, phase = 0;

function measure() {
  W = tank.clientWidth || 280; H = tank.clientHeight || 114;
  var dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  target = (used / TOTAL) * H;
}
function label() {
  usedEl.textContent = shown.toFixed(1);
  pctEl.textContent = Math.round((shown / TOTAL) * 100) + '%';
  btns[0].disabled = used <= 0;
  btns[1].disabled = used >= TOTAL;
}
