var tiles = [].slice.call(root.querySelectorAll('.mty-domino-stepper-tile'));
var stateEl = root.querySelector('.mty-domino-stepper-state');
var goBtn = root.querySelector('[data-a="go"]');
var resetBtn = root.querySelector('[data-a="reset"]');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var soft = !!(mq && mq.matches);
var NAMES = ['Draft', 'Review', 'Build', 'Ship'];
var N = tiles.length, S = [], i;
for (i = 0; i < N; i++) S.push({ th: 0, om: 0, rel: false, hit: false });
var LEAN = 0.55, PILE = 1.28, FLAT = 1.53, TORQUE = soft ? 90 : 27;
var running = false, last = 0, done = 0;

for (i = 0; i < N; i++) tiles[i].style.zIndex = String(N - i);

function restOf(k) {
  if (k === N - 1) return FLAT;
  return S[k + 1].th > 0.62 ? PILE : LEAN;
}
function paint() {
  for (var k = 0; k < N; k++) {
    tiles[k].style.transform = 'rotate(' + S[k].th.toFixed(4) + 'rad)';
    if (S[k].rel) tiles[k].setAttribute('data-done', '1'); else tiles[k].removeAttribute('data-done');
    if (!S[k].rel && k === done) tiles[k].setAttribute('data-cur', '1'); else tiles[k].removeAttribute('data-cur');
  }
}
function label() {
  if (done >= N) stateEl.textContent = 'All 4 stages shipped';
  else stateEl.textContent = 'Stage ' + (done + 1) + ' of ' + N + ' · ' + NAMES[done];
  goBtn.disabled = done >= N;
  resetBtn.disabled = done === 0;
}
function tick(dt) {
  for (var k = 0; k < N; k++) {
    var s = S[k], rest = restOf(k);
