      if (s.th < rest) {
        s.om += TORQUE * Math.sin(s.th + 0.14) * dt;
        s.th += s.om * dt;
        if (s.th >= rest) { s.th = rest; s.om = -s.om * 0.1; if (Math.abs(s.om) < 0.4) s.om = 0; }
