}
function frame(now) {
  if (!root.isConnected) { running = false; return; }
  var dt = Math.min(0.032, (now - last) / 1000); last = now;
  var n = 3;
  while (n--) tick(dt / 3);
  paint();
  if (calm()) {
    for (var k = 0; k < N; k++) { S[k].th = S[k].rel ? restOf(k) : 0; S[k].om = 0; }
