  if (done >= N) return;
  var s = S[done];
  s.rel = true; s.hit = true;
  if (soft) { s.th = restOf(done); s.om = 0; }
  else { s.hit = false; s.om += 2.6; s.th = Math.max(s.th, 0.04); }
