css:
.mty-orbit-cluster{--oc-a:#7dd3fc;padding:13px;border-radius:15px;background:linear-gradient(180deg,#0a0f1a,#070910);border:1px solid rgba(125,211,252,.14);color:#dceaf5;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}
.mty-orbit-cluster *{box-sizing:border-box}
.mty-orbit-cluster-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:9px}
.mty-orbit-cluster-eyebrow{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#6d8296}
.mty-orbit-cluster-sel{font-size:10.5px;color:var(--oc-a);font-variant-numeric:tabular-nums}
.mty-orbit-cluster-space{position:relative;height:158px;border-radius:12px;overflow:hidden;background:radial-gradient(60% 70% at 50% 50%,#0d1524,#06080e 72%);border:1px solid rgba(255,255,255,.06);touch-action:none}
.mty-orbit-cluster-cv{position:absolute;inset:0;width:100%;height:100%}
.mty-orbit-cluster-core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:#bfe9ff;background:radial-gradient(circle at 40% 35%,#2b6a92,#0d2233);border:1px solid rgba(125,211,252,.45);box-shadow:0 0 22px rgba(125,211,252,.28);pointer-events:none}
.mty-orbit-cluster-sat{position:absolute;left:0;top:0;display:inline-flex;align-items:center;gap:5px;padding:3px 8px 3px 5px;border-radius:20px;border:1px solid rgba(255,255,255,.12);background:rgba(10,16,26,.82);color:#b9cbdb;font-size:10.5px;font-weight:560;white-space:nowrap;cursor:grab;will-change:transform;transition:border-color .18s,color .18s,background .18s}
.mty-orbit-cluster-sat:hover{color:#fff;border-color:rgba(125,211,252,.6)}
.mty-orbit-cluster-sat:focus-visible{outline:2px solid var(--oc-a);outline-offset:2px}
.mty-orbit-cluster-sat[data-drag="1"]{cursor:grabbing;border-color:#fff}
.mty-orbit-cluster-sat[aria-pressed="true"]{color:#eaf8ff;border-color:var(--oc-a);background:rgba(20,52,74,.9);box-shadow:0 0 16px rgba(125,211,252,.25)}
.mty-orbit-cluster-dot{width:7px;height:7px;border-radius:50%;background:var(--oc-a);box-shadow:0 0 8px rgba(125,211,252,.8)}
.mty-orbit-cluster-foot{margin:9px 0 0;font-size:10.5px;color:#5d6f7e;line-height:1.4}
@media (prefers-reduced-motion: reduce){
.mty-orbit-cluster .mty-orbit-cluster-sat{transition:none;cursor:default}
.mty-orbit-cluster .mty-orbit-cluster-core{box-shadow:none}
}

