var space = root.querySelector('.mty-orbit-cluster-space');
var cv = root.querySelector('.mty-orbit-cluster-cv');
var ctx = cv.getContext('2d');
var selEl = root.querySelector('.mty-orbit-cluster-sel');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var soft = !!(mq && mq.matches);
var DATA = [
  { n: 'tools', r: 38, m: '14 calls/min' },
  { n: 'memory', r: 54, m: '2.1 k tokens' },
  { n: 'vision', r: 68, m: '6 frames/s' },
  { n: 'voice', r: 84, m: 'idle' }
];
var MU = 128000, sats = [], W = 0, H = 0, cx = 0, cy = 0, running = false, last = 0, acc = 0, sel = 0;

DATA.forEach(function (d, i) {
  var el = document.createElement('button');
  el.type = 'button';
  el.className = 'mty-orbit-cluster-sat';
  el.setAttribute('aria-pressed', i === 0 ? 'true' : 'false');
  el.innerHTML = '<span class="mty-orbit-cluster-dot" aria-hidden="true"></span>' + d.n;
  space.appendChild(el);
  var a = i * 1.7, v = Math.sqrt(MU / d.r);
  sats.push({
    el: el, d: d, x: Math.cos(a) * d.r, y: Math.sin(a) * d.r,
    vx: -Math.sin(a) * v, vy: Math.cos(a) * v,
    drag: false, px: 0, py: 0, pt: 0, moved: 0
  });
});
function size() {
  W = space.clientWidth || 260; H = space.clientHeight || 158;
  cx = W / 2; cy = H / 2;
  var dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = '#07090f';
  ctx.fillRect(0, 0, W, H);
}
function place(s) {
  s.el.style.transform = 'translate(' + (cx + s.x).toFixed(1) + 'px,' + (cy + s.y).toFixed(1) + 'px) translate(-50%,-50%)';
}
function physics(dt) {
  var lim = Math.min(W, H) / 2 - 12;
  for (var i = 0; i < sats.length; i++) {
    var s = sats[i];
    if (s.drag) continue;
    var r2 = s.x * s.x + s.y * s.y;
    var r = Math.sqrt(r2) || 0.001;
    if (r < 24) { var p = 24 / r; s.x *= p; s.y *= p; r = 24; r2 = 576; }
    var g = -MU / (r2 * r);
    s.vx += g * s.x * dt; s.vy += g * s.y * dt;
    if (r > lim) {
      var over = (r - lim) / lim;
      s.vx -= s.x / r * over * 2600 * dt;
      s.vy -= s.y / r * over * 2600 * dt;
      s.vx *= 0.985; s.vy *= 0.985;
    }
    s.x += s.vx * dt; s.y += s.vy * dt;
  }
}
function draw() {
  ctx.fillStyle = 'rgba(7,9,15,.20)';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'rgba(125,211,252,.09)';
  ctx.lineWidth = 1;
  for (var k = 0; k < sats.length; k++) {
    var s = sats[k];
    var r = Math.sqrt(s.x * s.x + s.y * s.y);
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = k === sel ? 'rgba(190,235,255,.95)' : 'rgba(125,211,252,.55)';
    ctx.beginPath(); ctx.arc(cx + s.x, cy + s.y, 2.1, 0, Math.PI * 2); ctx.fill();
    place(s);
  }
}
function frame(now) {
  if (!root.isConnected) { running = false; return; }
  if (space.clientWidth !== W || space.clientHeight !== H) size();
  acc += Math.min(0.06, (now - last) / 1000); last = now;
  var n = 0;
  while (acc > 1 / 240 && n < 12) { physics(1 / 240); acc -= 1 / 240; n++; }
  draw();
  requestAnimationFrame(frame);
}
function wake() {
  if (running || soft) return;
  running = true; last = performance.now(); acc = 0;
  requestAnimationFrame(frame);
}
function select(i) {
  sel = i;
  sats.forEach(function (s, k) { s.el.setAttribute('aria-pressed', k === i ? 'true' : 'false'); });
  selEl.textContent = sats[i].d.n + ' · ' + sats[i].d.m;
}
sats.forEach(function (s, i) {
  s.el.addEventListener('pointerdown', function (e) {
    if (soft) return;
    s.drag = true; s.moved = 0;
    s.px = e.clientX; s.py = e.clientY; s.pt = performance.now();
    s.el.setAttribute('data-drag', '1');
    s.el.setPointerCapture(e.pointerId);
    wake();
  });
  s.el.addEventListener('pointermove', function (e) {
    if (!s.drag) return;
    var r = space.getBoundingClientRect();
    var nx = e.clientX - r.left - cx, ny = e.clientY - r.top - cy;
    var now = performance.now(), dt = Math.max(10, now - s.pt) / 1000;
    s.moved += Math.abs(e.clientX - s.px) + Math.abs(e.clientY - s.py);
    s.vx = (nx - s.x) / dt * 0.6; s.vy = (ny - s.y) / dt * 0.6;
    s.x = nx; s.y = ny;
    s.px = e.clientX; s.py = e.clientY; s.pt = now;
    place(s);
  });
  function up() {
    if (!s.drag) return;
    s.drag = false;
    s.el.removeAttribute('data-drag');
    var sp = Math.sqrt(s.vx * s.vx + s.vy * s.vy);
    if (sp > 900) { s.vx *= 900 / sp; s.vy *= 900 / sp; }
    if (s.moved < 6) {
      var r = Math.sqrt(s.x * s.x + s.y * s.y) || 1;
      var v = Math.sqrt(MU / r);
      s.vx = -s.y / r * v; s.vy = s.x / r * v;
    }
    wake();
  }
  s.el.addEventListener('pointerup', up);
  s.el.addEventListener('pointercancel', up);
  s.el.addEventListener('click', function () { select(i); });
});
size();
if (soft) {
  sats.forEach(function (s) { place(s); });
  ctx.fillStyle = 'rgba(125,211,252,.10)';
  sats.forEach(function (s) {
    var r = Math.sqrt(s.x * s.x + s.y * s.y);
    ctx.strokeStyle = 'rgba(125,211,252,.14)';
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
  });
} else wake();
select(0);
